"""Generated by AetherLab - scenario: Kepler's stopwatch (revised)."""

import numpy as np
from manim import *


class AetherLabScene(Scene):
    def construct(self):
        # -----------------------------------------------------------------
        # OPENING: title + governing equation, kept brief.
        # -----------------------------------------------------------------
        title = Text("Kepler's stopwatch", font_size=40, weight=BOLD, color=YELLOW)
        title.to_edge(UP, buff=0.4)

        equation = MathTex(
            r"\tfrac{dA}{dt} = \tfrac{L}{2m} = \text{const}",
            font_size=42, color=WHITE,
        )
        equation.next_to(title, DOWN, buff=0.55)

        sub = Text(
            "Equal areas swept in equal times.",
            font_size=26, color=TEAL_A,
        )
        sub.next_to(equation, DOWN, buff=0.35)

        opening = VGroup(title, equation, sub)
        if opening.width > 12.4:
            opening.scale_to_fit_width(12.4)

        self.play(FadeIn(title, shift=0.25 * DOWN), run_time=0.7)
        self.play(FadeIn(equation, shift=0.2 * UP), run_time=0.7)
        self.play(FadeIn(sub, shift=0.2 * UP), run_time=0.6)
        self.wait(0.8)
        # Slide the intro up out of the way instead of clearing.
        self.play(
            VGroup(title, equation, sub).animate.shift(3.4 * UP).set_opacity(0),
            run_time=0.7,
        )
        self.remove(title, equation, sub)

        # -----------------------------------------------------------------
        # DATA: orbit path and per-tick measurements.
        # -----------------------------------------------------------------
        path = [[-0.3, -0.35], [-0.3004, -0.3077], [-0.3017, -0.2654], [-0.3039, -0.2231], [-0.3068, -0.1808], [-0.3107, -0.1386], [-0.3154, -0.0964], [-0.321, -0.0542], [-0.3274, -0.0121], [-0.3347, 0.0299], [-0.3428, 0.0719], [-0.3518, 0.1138], [-0.3617, 0.1556], [-0.3724, 0.1973], [-0.384, 0.2389], [-0.3965, 0.2804], [-0.4098, 0.3217], [-0.424, 0.363], [-0.4391, 0.4041], [-0.455, 0.445], [-0.4719, 0.4858], [-0.4895, 0.5265], [-0.5081, 0.5669], [-0.5276, 0.6072], [-0.5479, 0.6473], [-0.5691, 0.6872], [-0.5912, 0.7269], [-0.6142, 0.7663], [-0.6381, 0.8056], [-0.6629, 0.8446], [-0.6886, 0.8833], [-0.7152, 0.9218], [-0.7427, 0.96], [-0.7711, 0.9979], [-0.8005, 1.0355], [-0.8307, 1.0729], [-0.8619, 1.1099], [-0.894, 1.1465], [-0.927, 1.1829], [-0.9609, 1.2188], [-0.9958, 1.2545], [-1.0316, 1.2897], [-1.0684, 1.3245], [-1.1062, 1.3589], [-1.1448, 1.3929], [-1.1845, 1.4265], [-1.2251, 1.4596], [-1.2667, 1.4922], [-1.3092, 1.5243], [-1.3528, 1.556], [-1.3973, 1.5871], [-1.4428, 1.6176], [-1.4893, 1.6477], [-1.5368, 1.6771], [-1.5854, 1.7059], [-1.6349, 1.7341], [-1.6855, 1.7617], [-1.7371, 1.7886], [-1.7897, 1.8148], [-1.8433, 1.8403], [-1.8981, 1.8651], [-1.9538, 1.8891], [-2.0107, 1.9123], [-2.0685, 1.9347], [-2.1275, 1.9562], [-2.1875, 1.9769], [-2.2487, 1.9966], [-2.3109, 2.0154], [-2.3742, 2.0332], [-2.4386, 2.05], [-2.5042, 2.0657], [-2.5708, 2.0803], [-2.6386, 2.0938], [-2.7074, 2.1061], [-2.7775, 2.1172], [-2.8486, 2.127], [-2.9209, 2.1354], [-2.9943, 2.1424], [-3.0689, 2.148], [-3.1445, 2.1521], [-3.2214, 2.1546], [-3.2993, 2.1555], [-3.3784, 2.1546], [-3.4587, 2.152], [-3.54, 2.1475], [-3.6224, 2.141], [-3.706, 2.1324], [-3.7906, 2.1218], [-3.8762, 2.1088], [-3.9629, 2.0935], [-4.0506, 2.0758], [-4.1393, 2.0554], [-4.2288, 2.0324], [-4.3193, 2.0064], [-4.4105, 1.9775], [-4.5025, 1.9454], [-4.5951, 1.91], [-4.6882, 1.8711], [-4.7818, 1.8285], [-4.8757, 1.7821], [-4.9697, 1.7315], [-5.0637, 1.6768], [-5.1574, 1.6175], [-5.2507, 1.5535], [-5.3431, 1.4846], [-5.4345, 1.4106], [-5.5243, 1.3312], [-5.6123, 1.2463], [-5.6979, 1.1556], [-5.7806, 1.0591], [-5.8597, 0.9567], [-5.9347, 0.8482], [-6.0048, 0.7338], [-6.0692, 0.6137], [-6.1272, 0.488], [-6.178, 0.3572], [-6.2208, 0.2218], [-6.255, 0.0824], [-6.2798, -0.0599], [-6.2949, -0.2044], [-6.3, -0.35], [-6.2949, -0.4956], [-6.2798, -0.6401], [-6.255, -0.7825], [-6.2208, -0.9218], [-6.178, -1.0572], [-6.1272, -1.188], [-6.0692, -1.3137], [-6.0048, -1.4339], [-5.9347, -1.5482], [-5.8597, -1.6567], [-5.7806, -1.7591], [-5.6979, -1.8557], [-5.6123, -1.9463], [-5.5243, -2.0312], [-5.4345, -2.1106], [-5.3431, -2.1846], [-5.2507, -2.2535], [-5.1574, -2.3175], [-5.0637, -2.3768], [-4.9697, -2.4316], [-4.8757, -2.4821], [-4.7818, -2.5285], [-4.6882, -2.5711], [-4.5951, -2.61], [-4.5024, -2.6454], [-4.4105, -2.6775], [-4.3193, -2.7065], [-4.2288, -2.7324], [-4.1393, -2.7555], [-4.0506, -2.7758], [-3.9629, -2.7936], [-3.8762, -2.8088], [-3.7906, -2.8218], [-3.706, -2.8324], [-3.6224, -2.841], [-3.54, -2.8475], [-3.4586, -2.852], [-3.3784, -2.8546], [-3.2993, -2.8555], [-3.2214, -2.8546], [-3.1445, -2.8521], [-3.0688, -2.848], [-2.9943, -2.8424], [-2.9209, -2.8354], [-2.8486, -2.827], [-2.7774, -2.8172], [-2.7074, -2.8061], [-2.6385, -2.7938], [-2.5708, -2.7803], [-2.5041, -2.7657], [-2.4386, -2.75], [-2.3742, -2.7332], [-2.3109, -2.7154], [-2.2487, -2.6966], [-2.1875, -2.6768], [-2.1275, -2.6562], [-2.0685, -2.6347], [-2.0106, -2.6123], [-1.9538, -2.5891], [-1.898, -2.5651], [-1.8433, -2.5403], [-1.7897, -2.5148], [-1.737, -2.4886], [-1.6854, -2.4617], [-1.6349, -2.4341], [-1.5853, -2.4059], [-1.5368, -2.3771], [-1.4893, -2.3476], [-1.4428, -2.3176], [-1.3973, -2.2871], [-1.3527, -2.2559], [-1.3092, -2.2243], [-1.2667, -2.1922], [-1.2251, -2.1595], [-1.1845, -2.1264], [-1.1448, -2.0929], [-1.1061, -2.0589], [-1.0684, -2.0245], [-1.0316, -1.9897], [-0.9958, -1.9544], [-0.9609, -1.9188], [-0.927, -1.8828], [-0.894, -1.8465], [-0.8619, -1.8098], [-0.8307, -1.7728], [-0.8005, -1.7355], [-0.7711, -1.6979], [-0.7427, -1.66], [-0.7152, -1.6217], [-0.6886, -1.5833], [-0.6629, -1.5445], [-0.6381, -1.5055], [-0.6142, -1.4663], [-0.5912, -1.4268], [-0.5691, -1.3872], [-0.5479, -1.3473], [-0.5276, -1.3072], [-0.5081, -1.2669], [-0.4896, -1.2264], [-0.4719, -1.1858], [-0.455, -1.145], [-0.4391, -1.104], [-0.424, -1.0629], [-0.4098, -1.0217], [-0.3965, -0.9803], [-0.384, -0.9388], [-0.3724, -0.8972], [-0.3617, -0.8555], [-0.3519, -0.8137], [-0.3428, -0.7718], [-0.3347, -0.7299], [-0.3274, -0.6878], [-0.321, -0.6457], [-0.3154, -0.6036], [-0.3107, -0.5614], [-0.3069, -0.5191], [-0.3039, -0.4769], [-0.3017, -0.4346], [-0.3004, -0.3923], [-0.3, -0.3499]]
        star_pt = np.array([-4.95, -0.35, 0.0])
        dist_h = [0.53, 0.58, 0.68, 0.84, 1.12, 1.60, 1.60, 1.12, 0.84, 0.68, 0.58, 0.53]
        area_h = [1.60] * 12
        ticks, per_tick = 12, 20
        fast_color = TEAL   # fast / close to star
        slow_color = GOLD   # slow / far from star
        bar_colors = [slow_color, fast_color, fast_color, fast_color, slow_color, slow_color,
                      slow_color, slow_color, fast_color, fast_color, fast_color, slow_color]
        pts = [np.array(p + [0.0]) for p in path]

        # -----------------------------------------------------------------
        # SCENE FRAME
        # -----------------------------------------------------------------
        scene_title = Text("Kepler's stopwatch", font_size=30, color=YELLOW)
        scene_title.to_edge(UP, buff=0.2)

        # Orbit line.
        orbit = VMobject(color=BLUE_C, stroke_width=2.4, stroke_opacity=0.75)
        orbit.set_points_as_corners(pts)

        # Star.
        star = Dot(star_pt, color=ORANGE, radius=0.16, fill_opacity=1.0)
        halo = Dot(star_pt, color=YELLOW, radius=0.42).set_opacity(0.18)

        # -----------------------------------------------------------------
        # BAR CHARTS (right column).
        # -----------------------------------------------------------------
        chart_x_left = 1.6
        chart_x_right = 6.7
        bar_w = (chart_x_right - chart_x_left) / ticks

        # distance chart (top right)
        d_axis = Line([chart_x_left, 0.9, 0], [chart_x_right, 0.9, 0],
                      color=GREY_B, stroke_width=2)
        d_lab = Text("distance travelled per tick",
                     font_size=20, color=GREY_A).next_to(d_axis, DOWN, buff=0.12)
        d_axis_ylab = Text("d", font_size=22, color=GREY_B).next_to(
            d_axis, LEFT, buff=0.18)

        # area chart (bottom right)
        a_axis = Line([chart_x_left, -2.6, 0], [chart_x_right, -2.6, 0],
                      color=GREY_B, stroke_width=2)
        a_lab = Text("area swept per tick",
                     font_size=20, color=GREY_A).next_to(a_axis, DOWN, buff=0.12)
        a_axis_ylab = Text("A", font_size=22, color=GREY_B).next_to(
            a_axis, LEFT, buff=0.18)

        # Reference dotted line at full height (max) for area.
        area_ref = DashedLine(
            [chart_x_left, -2.6 + area_h[0], 0],
            [chart_x_right, -2.6 + area_h[0], 0],
            color=GREEN_E, stroke_width=1.2, dash_length=0.12,
        )
        area_ref_lab = Text("equal A", font_size=16, color=GREEN_E).next_to(
            area_ref, RIGHT, buff=0.12)

        # Bar groups (created empty; built per tick).
        dist_bars = VGroup()
        area_bars = VGroup()
        tick_dots = VGroup()  # tick markers on the orbit

        # Wedges for completed ticks.
        done_wedges = VGroup()

        # -----------------------------------------------------------------
        # ORBIT LEFT SIDE: animation, plus growing wedge and radius line.
        # -----------------------------------------------------------------
        idx = ValueTracker(0.0)

        def planet_pt():
            j = int(idx.get_value())
            j = max(0, min(j, len(pts) - 1))
            return pts[j]

        planet = always_redraw(lambda: Dot(planet_pt(), color=WHITE,
                                           radius=0.09, stroke_width=0))
        radius_line = always_redraw(
            lambda: Line(star_pt, planet_pt(),
                         color=GREY_B, stroke_width=1.6)
        )

        # Trailing tail (short arc) for visual speed cue.
        def tail():
            j = int(idx.get_value())
            start = max(0, j - 6)
            return VMobject(stroke_color=WHITE, stroke_width=2.4,
                            stroke_opacity=0.55).set_points_as_corners(
                pts[start:j + 1])

        tail_mob = always_redraw(tail)

        # The "in progress" wedge that grows as idx advances within a tick.
        def growing_wedge():
            j = int(idx.get_value())
            k = min(j // per_tick, ticks - 1)
            if j - k * per_tick < 1:
                return VMobject()
            return Polygon(
                star_pt,
                *pts[k * per_tick:j + 1],
                color=colors_for(k),
                fill_color=colors_for(k),
                fill_opacity=0.32,
                stroke_width=0,
            )

        def colors_for(k):
            return bar_colors[k]

        current_wedge = always_redraw(growing_wedge)

        # -----------------------------------------------------------------
        # Setter that materialises each completed tick's wedge + bars.
        # -----------------------------------------------------------------
        def settle(group):
            k = len(group)
            if k < ticks and idx.get_value() >= (k + 1) * per_tick:
                color = colors_for(k)
                # Finalise the wedge for tick k.
                wedge = Polygon(
                    star_pt,
                    *pts[k * per_tick:(k + 1) * per_tick + 1],
                    color=color, fill_color=color,
                    fill_opacity=0.42, stroke_width=0,
                )
                group.add(wedge)
                # Tick dot at end of arc.
                group.add(Dot(pts[(k + 1) * per_tick], color=color,
                              radius=0.05, stroke_width=0))

        done_wedges.add_updater(settle)

        # -----------------------------------------------------------------
        # BUILD SCENE.
        # -----------------------------------------------------------------
        self.play(
            FadeIn(scene_title),
            Create(orbit),
            FadeIn(halo),
            GrowFromCenter(star),
            run_time=1.2,
        )
        self.play(
            FadeIn(d_axis), FadeIn(d_lab), FadeIn(d_axis_ylab),
            FadeIn(a_axis), FadeIn(a_lab), FadeIn(a_axis_ylab),
            FadeIn(area_ref), FadeIn(area_ref_lab),
            run_time=0.8,
        )
        self.add(done_wedges, current_wedge, radius_line, planet, tail_mob,
                 dist_bars, area_bars)

        # -----------------------------------------------------------------
        # SWEEP: move planet through the orbit (bars/wedges are added in
        # parallel via updaters).
        # -----------------------------------------------------------------
        self.play(
            idx.animate.set_value(float(len(pts) - 1)),
            run_time=11.0, rate_func=linear,
        )

        # -----------------------------------------------------------------
        # TICK COMPLETION: build the bar chart values for every tick in
        # sequence, each labelled with its value.
        # -----------------------------------------------------------------
        # Finalise all remaining wedges first.
        for k in range(ticks):
            color = colors_for(k)
            wedge = Polygon(
                star_pt,
                *pts[k * per_tick:(k + 1) * per_tick + 1],
                color=color, fill_color=color,
                fill_opacity=0.42, stroke_width=0,
            )
            done_wedges.add(wedge)
            tick_dots.add(Dot(pts[(k + 1) * per_tick], color=color,
                              radius=0.05, stroke_width=0))

        done_wedges.clear_updaters()
        current_wedge.clear_updaters()
        self.remove(current_wedge)
        idx.set_value(len(pts) - 1)

        # Animate the bars in tick-by-tick (first three quickly so we don't
        # stall, then a steady rhythm).
        for k in range(ticks):
            x = chart_x_left + (k + 0.5) * bar_w
            color = colors_for(k)
            dbar = Rectangle(
                width=bar_w * 0.78, height=dist_h[k],
                fill_color=color, fill_opacity=0.9, stroke_width=0,
            ).move_to([x, 0.9 + dist_h[k] / 2, 0])
            abar = Rectangle(
                width=bar_w * 0.78, height=area_h[k],
                fill_color=color, fill_opacity=0.9, stroke_width=0,
            ).move_to([x, -2.6 + area_h[k] / 2, 0])
            rt = 0.18 if k < 3 else 0.32
            self.play(
                GrowFromEdge(dbar, DOWN), GrowFromEdge(abar, DOWN),
                run_time=rt,
            )
            dist_bars.add(dbar)
            area_bars.add(abar)

        # -----------------------------------------------------------------
        # ANNOTATIONS: value labels on the two extreme distance bars
        # and a small bracket over the equal area bars.
        # -----------------------------------------------------------------
        # Labels on the two extreme distance bars (slowest vs fastest).
        def dbar_x(k):
            return chart_x_left + (k + 0.5) * bar_w

        slow_x = dbar_x(0)
        fast_x = dbar_x(5)
        slow_lbl = MathTex("0.53", font_size=20, color=GOLD).next_to(
            [slow_x, 0.9 + dist_h[0], 0], UP, buff=0.12)
        fast_lbl = MathTex("1.60", font_size=20, color=TEAL).next_to(
            [fast_x, 0.9 + dist_h[5], 0], UP, buff=0.12)
        ratio_lbl = MathTex(r"\dfrac{v_{\max}}{v_{\min}} \approx 3.0\times",
                            font_size=24, color=ORANGE).move_to(
            [(chart_x_left + chart_x_right) / 2, 0.9 + 1.85, 0])

        # Equal-area highlight: a thin green line over the area bars.
        equal_line = Line(
            [chart_x_left + 0.05, -2.6 + area_h[0] + 0.05, 0],
            [chart_x_right - 0.05, -2.6 + area_h[0] + 0.05, 0],
            color=GREEN_B, stroke_width=2,
        )
        equal_lbl = Text("A = const", font_size=20, color=GREEN_B).next_to(
            equal_line, UP, buff=0.08).shift(0.35 * LEFT)

        self.play(
            FadeIn(slow_lbl, shift=0.15 * DOWN),
            FadeIn(fast_lbl, shift=0.15 * DOWN),
            run_time=0.7,
        )
        self.play(FadeIn(ratio_lbl, shift=0.2 * DOWN), run_time=0.6)
        self.play(Create(equal_line), FadeIn(equal_lbl), run_time=0.7)
        self.wait(0.6)

        # -----------------------------------------------------------------
        # LEGEND: explain the two colours and what they mean physically.
        # -----------------------------------------------------------------
        leg_y = -3.55
        leg_box = RoundedRectangle(
            width=11.6, height=0.9, corner_radius=0.12,
            stroke_color=GREY_C, stroke_width=1.2,
        ).set_fill(BLACK, opacity=0.55).move_to([0, leg_y, 0])

        sw1 = Rectangle(width=0.35, height=0.35,
                        fill_color=fast_color, fill_opacity=0.9,
                        stroke_width=0).move_to([-4.6, leg_y, 0])
        leg1 = Text("near star  →  fast, short arc", font_size=20,
                    color=GREY_A).next_to(sw1, RIGHT, buff=0.18)

        sw2 = Rectangle(width=0.35, height=0.35,
                        fill_color=slow_color, fill_opacity=0.9,
                        stroke_width=0).move_to([0.6, leg_y, 0])
        leg2 = Text("far from star  →  slow, long arc", font_size=20,
                    color=GREY_A).next_to(sw2, RIGHT, buff=0.18)

        legend = VGroup(leg_box, sw1, leg1, sw2, leg2)
        self.play(FadeIn(legend, shift=0.15 * UP), run_time=0.7)
        self.wait(0.5)

        # -----------------------------------------------------------------
        # HERO CLOSING: zoom-cue is a synthetic pan; instead we use a
        # SurroundingRectangle around the equal-area highlight and dim
        # the rest, then a final key sentence.
        # -----------------------------------------------------------------
        # Dim everything except the equal-area line and its label.
        everything = VGroup(
            scene_title, orbit, star, halo, planet, radius_line, tail_mob,
            done_wedges, tick_dots, dist_bars, area_bars,
            d_axis, d_lab, d_axis_ylab, a_axis, a_lab, a_axis_ylab,
            area_ref, area_ref_lab, slow_lbl, fast_lbl, ratio_lbl,
            legend,
        )
        dim_group = VGroup(
            scene_title, orbit, star, halo, planet, radius_line, tail_mob,
            done_wedges, tick_dots, dist_bars,
            d_axis, d_lab, d_axis_ylab, a_axis, a_lab, a_axis_ylab,
            area_ref, area_ref_lab, slow_lbl, fast_lbl, ratio_lbl,
            legend,
        )
        self.play(
            dim_group.animate.set_opacity(0.25),
            run_time=0.7,
        )

        hero_box = SurroundingRectangle(
            VGroup(equal_line, equal_lbl, area_bars),
            color=YELLOW, buff=0.18, stroke_width=3,
        )
        self.play(Create(hero_box), run_time=0.6)

        # Bring the close-up line and label back to full opacity.
        self.play(
            VGroup(equal_line, equal_lbl, hero_box, area_bars).animate.set_opacity(1),
            run_time=0.5,
        )

        closing = Text(
            "Equal areas in equal times.",
            font_size=34, weight=BOLD, color=YELLOW,
        ).next_to(hero_box, DOWN, buff=0.35)
        self.play(FadeIn(closing, shift=0.2 * UP), run_time=0.8)
        self.wait(2.0)

        # Living ending: pulse the equal-area line + hero box together so
        # the last sampled frames are clearly different from the still text.
        pulse_box = hero_box.copy().set_stroke(width=6)
        self.play(
            equal_line.animate.set_stroke(width=4),
            pulse_box.animate.set_stroke(width=8).scale(1.04),
            run_time=0.7,
        )
        self.play(
            equal_line.animate.set_stroke(width=2),
            FadeOut(pulse_box),
            run_time=0.7,
        )
        self.wait(1.0)